css:
.alliancelab-container {
    padding: 20px;
    background: linear-gradient(165deg, #0c1420 0%, #122033 55%, #0f1b2e 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #e6eef7;
}

/* ---- Header ---- */
.alliancelab-header {
    background: linear-gradient(135deg, #0d3b4f 0%, #11607a 45%, #122033 100%);
    color: #ffffff;
    padding: 32px 30px;
    border-radius: 16px;
    margin-bottom: 22px;
    box-shadow: 0 12px 30px rgba(0,0,0,0.45);
    text-align: center;
    position: relative;
    overflow: hidden;
    border: 1px solid rgba(45,212,191,0.18);
}

.alliancelab-header::before {
    content: '';
    position: absolute;
    top: -50%;
    left: -50%;
    width: 200%;
    height: 200%;
    background: radial-gradient(circle, rgba(45,212,191,0.10) 0%, transparent 60%);
    pointer-events: none;
}

.alliancelab-header-icon {
    font-size: 2.6rem;
    margin-bottom: 8px;
}

.alliancelab-header h1 {
    font-size: 1.85rem;
    font-weight: 800;
    margin-bottom: 6px;
    letter-spacing: 0.3px;
}

.alliancelab-header p {
    font-size: 1rem;
    opacity: 0.9;
    margin: 0 0 14px 0;
}

.alliancelab-clock {
    display: inline-block;
    background: rgba(0,0,0,0.35);
    border: 1px solid rgba(45,212,191,0.3);
    border-radius: 999px;
    padding: 6px 18px;
    font-size: 0.92rem;
    font-weight: 600;
    letter-spacing: 0.4px;
}

.alliancelab-clock #clockDisplay {
    color: #ffcf5c;
    font-weight: 800;
    margin: 0 4px;
}

/* ---- Period counter ---- */
.alliancelab-period-counter {
    text-align: center;
    font-size: 1.05rem;
    color: #aebfd4;
    margin-bottom: 22px;
    font-weight: 600;
}

.alliancelab-period-counter span {
    margin: 0 3px;
}

.alliancelab-period-counter #currentDay,
.alliancelab-period-counter #maxPeriods {
    color: #2dd4bf;
    font-weight: 800;
}

.alliancelab-round-name {
    display: inline-block;
    margin-left: 10px;
    padding: 3px 14px;
    background: rgba(45,212,191,0.16);
    border: 1px solid rgba(45,212,191,0.4);
    border-radius: 999px;
    color: #8ff0e3;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
}

/* ---- KPI cards ---- */
.alliancelab-kpi-section {
    margin-bottom: 22px;
}

.alliancelab-kpi-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
    margin-bottom: 16px;
}

.alliancelab-kpi-cards-secondary {
    grid-template-columns: repeat(3, 1fr);
    margin-bottom: 0;
}

.alliancelab-kpi-card {
    background: linear-gradient(160deg, #16263c 0%, #122033 100%);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 14px;
    padding: 18px 18px 20px;
    box-shadow: 0 6px 18px rgba(0,0,0,0.3);
    transition: transform 0.18s ease, box-shadow 0.18s ease;
}

.alliancelab-kpi-card:hover {
    transform: translateY(-3px);
    box-shadow: 0 10px 26px rgba(0,0,0,0.45);
}

.alliancelab-kpi-hero {
    border: 1px solid rgba(45,212,191,0.4);
    background: linear-gradient(160deg, #0f3530 0%, #122033 100%);
}

.alliancelab-kpi-label {
    font-size: 0.8rem;
    color: #93a6c2;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    margin-bottom: 8px;
    font-weight: 600;
}

.alliancelab-kpi-value {
    font-size: 2.6rem;
    font-weight: 800;
    color: #ffffff;
    line-height: 1.05;
}

.alliancelab-kpi-hero .alliancelab-kpi-value {
    color: #2dd4bf;
}

.alliancelab-bad {
    color: #ff7a92 !important;
}

.alliancelab-kpi-small .alliancelab-kpi-value {
    font-size: 1.5rem;
}

.alliancelab-kpi-sub {
    font-size: 0.74rem;
    color: #7587a6;
    margin-top: 8px;
    line-height: 1.3;
}

.alliancelab-kpi-bar-bg {
    height: 8px;
    background: rgba(255,255,255,0.1);
    border-radius: 6px;
    margin-top: 12px;
    overflow: hidden;
}

.alliancelab-kpi-bar-fill {
    height: 100%;
    border-radius: 6px;
    transition: width 0.5s ease;
}

.alliancelab-creativity-fill { background: linear-gradient(90deg, #14b8a6, #2dd4bf); }
.alliancelab-trust-fill { background: linear-gradient(90deg, #3b82f6, #60a5fa); }
.alliancelab-iprisk-fill { background: linear-gradient(90deg, #f97316, #ff7a92); }
.alliancelab-roi-fill { background: linear-gradient(90deg, #a855f7, #c084fc); }

/* ---- Briefing ---- */
.alliancelab-briefing {
    background: linear-gradient(160deg, #16263c 0%, #122033 100%);
    border: 1px solid rgba(255,255,255,0.08);
    border-left: 4px solid #2dd4bf;
    border-radius: 14px;
    padding: 22px 24px;
    margin-bottom: 22px;
    box-shadow: 0 6px 18px rgba(0,0,0,0.3);
}

.alliancelab-briefing h3 {
    font-size: 1.15rem;
    font-weight: 700;
    margin-bottom: 14px;
    color: #2dd4bf;
}

.alliancelab-briefing-text {
    font-size: 0.96rem;
    line-height: 1.65;
    color: #cdd9ec;
}

.alliancelab-briefing-text strong {
    color: #ffffff;
}

.alliancelab-briefing-text em {
    color: #8ff0e3;
    font-style: italic;
}

.alliancelab-event-alert {
    margin-top: 16px;
    padding: 14px 16px;
    background: rgba(249,115,22,0.14);
    border: 1px solid rgba(249,115,22,0.45);
    border-radius: 10px;
    color: #ffd9b0;
    font-size: 0.92rem;
    line-height: 1.55;
}

/* ---- Controls ---- */
.alliancelab-controls {
    background: linear-gradient(160deg, #16263c 0%, #122033 100%);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 14px;
    padding: 24px;
    margin-bottom: 22px;
    box-shadow: 0 6px 18px rgba(0,0,0,0.3);
}

.alliancelab-controls h3 {
    font-size: 1.2rem;
    font-weight: 700;
    margin-bottom: 6px;
    color: #ffffff;
}

.alliancelab-decisions-note {
    font-size: 0.86rem;
    color: #93a6c2;
    margin-bottom: 18px;
    font-style: italic;
}

.alliancelab-input-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 18px 22px;
}

.alliancelab-input-group {
    display: flex;
    flex-direction: column;
}

.alliancelab-input-group label {
    font-size: 0.9rem;
    font-weight: 600;
    color: #c4d1e6;
    margin-bottom: 7px;
}

.alliancelab-container .form-control {
    background-color: #0d1726;
    color: #eef4fc;
    border: 1px solid rgba(255,255,255,0.16);
    border-radius: 8px;
    padding: 10px 12px;
    font-size: 0.95rem;
}

.alliancelab-container .form-control:focus {
    border-color: #2dd4bf;
    box-shadow: 0 0 0 3px rgba(45,212,191,0.18);
    background-color: #0d1726;
    color: #eef4fc;
    outline: none;
}

.alliancelab-container select.form-control {
    background-color: #0d1726;
    color: #eef4fc;
}

.alliancelab-container select.form-control option {
    background-color: #0d1726;
    color: #eef4fc;
}

.alliancelab-hint {
    font-size: 0.76rem;
    color: #7587a6;
    margin-top: 6px;
    line-height: 1.35;
}

.alliancelab-btn-row {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-top: 22px;
    flex-wrap: wrap;
}

.alliancelab-container .btn-primary {
    background: linear-gradient(135deg, #0d6e8c 0%, #2dd4bf 100%);
    border: none;
    font-weight: 700;
    letter-spacing: 0.4px;
    padding: 12px 30px;
    border-radius: 10px;
    color: #06141a;
    box-shadow: 0 6px 16px rgba(13,110,140,0.4);
}

.alliancelab-container .btn-primary:hover {
    background: linear-gradient(135deg, #117e9f 0%, #45e0cd 100%);
    color: #04111a;
}

.alliancelab-container .btn-outline-secondary {
    color: #aebfd4;
    border-color: rgba(255,255,255,0.25);
    border-radius: 10px;
}

.alliancelab-container .btn-outline-secondary:hover {
    background: rgba(255,255,255,0.08);
    color: #ffffff;
}

/* ---- Charts ---- */
.alliancelab-charts {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 18px;
    margin-bottom: 22px;
}

.alliancelab-chart-box {
    background: #f6f9fc;
    border-radius: 14px;
    padding: 16px;
    box-shadow: 0 6px 18px rgba(0,0,0,0.3);
    min-height: 320px;
}

/* ---- History ---- */
.alliancelab-history {
    background: linear-gradient(160deg, #16263c 0%, #122033 100%);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 14px;
    padding: 22px 24px;
    box-shadow: 0 6px 18px rgba(0,0,0,0.3);
}

.alliancelab-history h3 {
    font-size: 1.1rem;
    font-weight: 700;
    margin-bottom: 14px;
    color: #ffffff;
}

.alliancelab-history table {
    color: #cdd9ec;
    margin-bottom: 0;
}

.alliancelab-history .table-striped tbody tr:nth-of-type(odd) {
    background-color: rgba(255,255,255,0.04);
}

.alliancelab-history th {
    color: #93a6c2;
    border-color: rgba(255,255,255,0.12);
    font-size: 0.82rem;
    text-transform: uppercase;
    letter-spacing: 0.4px;
}

.alliancelab-history td {
    border-color: rgba(255,255,255,0.08);
    font-size: 0.88rem;
}

/* ---- Responsive ---- */
@media (max-width: 768px) {
    .alliancelab-container {
        padding: 12px;
    }
    .alliancelab-header h1 {
        font-size: 1.4rem;
    }
    .alliancelab-kpi-cards,
    .alliancelab-kpi-cards-secondary {
        grid-template-columns: 1fr;
    }
    .alliancelab-input-grid {
        grid-template-columns: 1fr;
    }
    .alliancelab-charts {
        grid-template-columns: 1fr;
    }
    .alliancelab-kpi-value {
        font-size: 2.1rem;
    }
}


/* FIX v1.1.0 — completion / board-debrief screen */
.al-completion { padding: 10px 6px; text-align: center; }
.al-completion-heading { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: #64748b; margin-bottom: 6px; }
.al-completion-verdict { font-size: 20px; font-weight: 700; color: #0f172a; margin-bottom: 8px; }
.al-completion-score { font-size: 16px; color: #0f172a; margin-bottom: 14px; }
.al-completion-score strong { color: #0d9488; }
.al-completion-metrics { display: flex; flex-wrap: wrap; justify-content: center; gap: 10px; margin-bottom: 16px; }
.al-completion-metric { display: inline-flex; flex-direction: column; align-items: center; gap: 2px; padding: 8px 12px; background: #f1f5f9; border-radius: 8px; min-width: 100px; }
.al-completion-metric span { font-size: 11px; letter-spacing: .03em; text-transform: uppercase; color: #64748b; }
.al-completion-metric strong { font-size: 16px; color: #0f172a; }
.al-completion-insights { list-style: none; padding: 0; margin: 0 auto; max-width: 700px; text-align: left; }
.al-completion-insights li { padding: 9px 13px; margin-bottom: 7px; background: #f0fdfa; border-left: 3px solid #0d9488; border-radius: 4px; color: #1e293b; font-size: 13px; }

